function ragContext(q){
  if(!attachedText)return '';
  const normalize=s=>s.toLowerBy?'' : s.toLowerCase().replace(/[âàáä]/g,'a').replace(/[îìíï]/g,'i').replace(/[ûùúü]/g,'u').replace(/[êèéë]/g,'e').replace(/[ôòóö]/g,'o').replace(/[ç]/g,'c').replace(/[ğ]/g,'g').replace(/[ş]/g,'s');
  const terms=normalize(q).match(/[\p{L}\p{N}]{3,}/gu)||[];
  const chunks=attachedText.split(/\n\s*\n|(?<=.{700})/g).filter(Boolean);
  return chunks.map((c,i)=>{const n=normalize(c);let score=terms.reduce((s,t)=>s+(n.includes(t)?3:0),0);return {i,c,score}}).sort((a,b)=>b.score-a.score).slice(0,4).map(x=>x.c).join('\n\n').slice(0,9000);
}
function localAnswer(q){
  const raw=String(q||'').trim(), t=raw.toLowerCase(), context=ragContext(raw);
  const time=(()=>{try{return new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',dateStyle:'full',timeStyle:'medium'}).format(new Date())+' (Europe/Istanbul, UTC+3)'}catch(e){return 'Geçerli yerel saat kullanılamadı'}})();
  if(/(sen kimsin|neler yapabilirsin|kim olduğun|özelliklerin|what are you|who are you|what can you do)/.test(t))return '<h2>Ben gemini.AI.upgreaded</h2><p>Türkçe ve İngilizce sorulara doğrudan yanıt veren, planlama, çeviri, kod inceleme, özetleme, çalışma rehberi ve oyun tasarımı konularında yardımcı olan tarayıcı içi bir asistanım.</p><ul><li>API anahtarıyla uygun Gemini modellerine bağlanabilirim.</li><li>API erişimi olmasa bile isteğin türünü anlayıp yapılandırılmış yanıt verebilirim.</li><li><b>＋</b> ile yüklenen metin dosyalarını yerel bağlam olarak kullanabilirim.</li></ul>';
  if(/\b(saat kaç|tarih|bugün|current time|date today|today)\b/.test(t))return '<h2>Güncel saat ve tarih</h2><p><b>'+esc(time)+'.</b></p><p>Bu değer cihaz saatinden alınmıştır; dakikalar geçtikçe İstanbul saati otomatik güncellenir.</p>';
  const trMatch=raw.match(/(?:çevir|tercüme et)[,:]?\s*["'“]?(.+?)["'”]?\s*(?:turkçe|türkçe|ingilizce|almanca|fransızca|arapça|span|english)/i);
  if(/(çevir|translate|translation|tercüme)/.test(t)){
    const pair=raw.match(/(.+?)\s+(?:→|to|into|–|—)\s+(.+)/i);
    let out='<h2>Çeviri talebi</h2><p>Metni ve hedef dili açıkça belirterek en doğru sonucu verebilirim. Örneğin:</p><ul><li><b>“Merhaba, nasılsın?” → İngilizce</b></li><li><b>Translate “good morning” into Turkish.</b></li></ul>';
